import string

def check_flag(data):
    eax = 0x811c9dc5
    for b in data:
        edx = (b ^ eax) & 0xffffffff
        eax = (edx * 0x1000193) & 0xffffffff
    return edx

target_edx = 0xcfb2ee18

# Try alphanumeric lower + digits
charset = string.ascii_lowercase + string.digits

print("Trying 4-char alphanumeric strings...")
found = False
for c1 in charset:
    if found:
        break
    for c2 in charset:
        if found:
            break
        for c3 in charset:
            if found:
                break
            for c4 in charset:
                s = (c1+c2+c3+c4).encode()
                if check_flag(s) == target_edx:
                    print(f"Found: {c1}{c2}{c3}{c4}")
                    found = True
                    break

if not found:
