def check_hash(data):
    eax = 0x811c9dc5
    edx = 0
    for b in data:
        edx = (b ^ eax) & 0xffffffff
        eax = (edx * 0x1000193) & 0xffffffff
    return edx

target = 0xcfb2ee18

# Let me read the binary and extract all strings, then check each
import os
target_binary = os.environ.get('TARGET', '/work/target')

with open(target_binary, 'rb') as f:
    data = f.read()

# Find all printable strings of length 4+
strings_found = []
current = b''
for b in data:
    if 32 <= b < 127:
        current += bytes([b])
    else:
        if len(current) >= 4:
            strings_found.append(current.decode('ascii', errors='ignore'))
        current = b''

print(f"Found {len(strings_found)} strings of length >= 4")

# Check each string as potential flag content
for s in strings_found:
    h = check_hash(s.encode())
    if h == target:
        print(f"FOUND: '{s}'")

# Also check substrings
for s in strings_found:
    for start in range(len(s)):
        for end in range(start+1, min(start+20, len(s)+1)):
            sub = s[start:end]
            h = check_hash(sub.encode())
            if h == target:
                print(f"FOUND substring: '{sub}' from '{s}'")

print("String search done")
